	"cancelled",
	"failed",
] as const;
export type WorkflowStatus = (typeof WORKFLOW_STATUSES)[number];

export const EXECUTION_STATUSES = [
	"pending",
	"running",
	"sleeping",
	"waiting",
	"awaiting_approval",
	"completed",
	"failed",
