import { pgEnum } from "drizzle-orm/pg-core";

import {
	ACTIVITY_STATUSES,
	ACTIVITY_TYPES,
	API_PROVIDERS,
	APPROVAL_STATUSES,
	GROUP_KINDS,
	INVITE_KINDS,
	INVITE_STATUSES,
	MESSAGE_ROLES,
	MESSAGE_STATUSES,
	NOTIFICATION_TYPES,
	PLAN_LEVELS,
	PLAN_STATUSES,
	PLAN_STEP_STATUSES,
	ROLES,
	RUN_STATUSES,
	RUN_TRIGGERS,
	THREAD_ROLES,
	WORKFLOW_STATUSES,
} from "../domain";

export const roleEnum = pgEnum("role", ROLES);
export const threadRoleEnum = pgEnum("thread_role", THREAD_ROLES);
export const planLevelEnum = pgEnum("plan_level", PLAN_LEVELS);
export const groupKindEnum = pgEnum("group_kind", GROUP_KINDS);
export const inviteKindEnum = pgEnum("invite_kind", INVITE_KINDS);
export const inviteStatusEnum = pgEnum("invite_status", INVITE_STATUSES);
export const workflowStatusEnum = pgEnum("workflow_status", WORKFLOW_STATUSES);
export const messageRoleEnum = pgEnum("message_role", MESSAGE_ROLES);
export const messageStatusEnum = pgEnum("message_status", MESSAGE_STATUSES);
export const runStatusEnum = pgEnum("run_status", RUN_STATUSES);
export const runTriggerEnum = pgEnum("run_trigger", RUN_TRIGGERS);
export const activityStatusEnum = pgEnum("activity_status", ACTIVITY_STATUSES);
export const activityTypeEnum = pgEnum("activity_type", ACTIVITY_TYPES);
export const approvalStatusEnum = pgEnum("approval_status", APPROVAL_STATUSES);
export const apiProviderEnum = pgEnum("api_provider", API_PROVIDERS);
export const planStatusEnum = pgEnum("plan_status", PLAN_STATUSES);
export const planStepStatusEnum = pgEnum("plan_step_status", PLAN_STEP_STATUSES);
export const notificationTypeEnum = pgEnum("notification_type", NOTIFICATION_TYPES);

import { boolean, pgTable, text, timestamp, uniqueIndex, uuid } from "drizzle-orm/pg-core";

// FK to auth.users (outside drizzle schema) is enforced in SQL migration.
export const workspaces = pgTable(
	"workspaces",
	{
		id: text("id").primaryKey(),
		name: text("name").notNull(),
		createdBy: uuid("created_by").notNull(),
		isDefault: boolean("is_default").notNull().default(false),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
		updatedAt: timestamp("updated_at", { withTimezone: true })
			.defaultNow()
			.notNull()
			.$onUpdate(() => new Date()),
	},
	(table) => [uniqueIndex("workspaces_created_by_name_idx").on(table.createdBy, table.name)],
);

export type Workspace = typeof workspaces.$inferSelect;
export type NewWorkspace = typeof workspaces.$inferInsert;

import { index, integer, pgTable, text, timestamp, uniqueIndex, uuid } from "drizzle-orm/pg-core";

import { groupKindEnum } from "./enums";
import { workspaces } from "./workspace";

export const groups = pgTable(
	"groups",
	{
		id: text("id").primaryKey(),
		workspaceId: text("workspace_id")
			.notNull()
			.references(() => workspaces.id, { onDelete: "cascade" }),
		userId: uuid("user_id").notNull(),
		name: text("name").notNull(),
		kind: groupKindEnum("kind").notNull().default("custom"),
		position: integer("position").notNull().default(0),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
		updatedAt: timestamp("updated_at", { withTimezone: true })
			.defaultNow()
			.notNull()
			.$onUpdate(() => new Date()),
	},
	(table) => [
		uniqueIndex("groups_workspace_name_idx").on(table.workspaceId, table.name),
		index("groups_workspace_position_idx").on(table.workspaceId, table.position),
	],
);

export type Group = typeof groups.$inferSelect;
export type NewGroup = typeof groups.$inferInsert;

import { pgTable, text, timestamp, uniqueIndex, uuid } from "drizzle-orm/pg-core";

import { roleEnum } from "./enums";
import { workspaces } from "./workspace";

export const workspaceMembers = pgTable(
	"workspace_members",
	{
		id: text("id").primaryKey(),
		workspaceId: text("workspace_id")
			.notNull()
			.references(() => workspaces.id, { onDelete: "cascade" }),
		userId: uuid("user_id").notNull(),
		role: roleEnum("role").notNull().default("viewer"),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
	},
	(table) => [
		uniqueIndex("workspace_members_workspace_user_idx").on(
			table.workspaceId,
			table.userId,
		),
	],
);

export type WorkspaceMember = typeof workspaceMembers.$inferSelect;
export type NewWorkspaceMember = typeof workspaceMembers.$inferInsert;

import { boolean, jsonb, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

import { planLevelEnum } from "./enums";

export const userProfiles = pgTable("user_profiles", {
	id: text("id").primaryKey(),
	userId: uuid("user_id").notNull().unique(),
	onboarded: boolean("onboarded").notNull().default(false),
	preAnswers: jsonb("pre_answers"),
	plan: planLevelEnum("plan").notNull().default("free"),
	preferOwnKeysInShared: boolean("prefer_own_keys_in_shared")
		.notNull()
		.default(false),
	createdAt: timestamp("created_at", { withTimezone: true })
		.defaultNow()
		.notNull(),
	updatedAt: timestamp("updated_at", { withTimezone: true })
		.defaultNow()
		.notNull()
		.$onUpdate(() => new Date()),
});

export type UserProfile = typeof userProfiles.$inferSelect;
export type NewUserProfile = typeof userProfiles.$inferInsert;

import { boolean, index, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

import { groups } from "./group";
import { workspaces } from "./workspace";

export const threads = pgTable(
	"threads",
	{
		id: text("id").primaryKey(),
		workspaceId: text("workspace_id")
			.notNull()
			.references(() => workspaces.id, { onDelete: "cascade" }),
		groupId: text("group_id").references(() => groups.id, {
			onDelete: "set null",
		}),
		userId: uuid("user_id").notNull(),
		title: text("title").notNull().default(""),
		deletedAt: timestamp("deleted_at", { withTimezone: true }),
		shareEnabled: boolean("share_enabled").notNull().default(false),
		boundWorkflowId: text("bound_workflow_id"),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
		updatedAt: timestamp("updated_at", { withTimezone: true })
			.defaultNow()
			.notNull()
			.$onUpdate(() => new Date()),
		lastMessageAt: timestamp("last_message_at", { withTimezone: true }),
	},
	(table) => [
		index("threads_user_workspace_last_msg_idx").on(
			table.userId,
			table.workspaceId,
			table.lastMessageAt,
		),
		index("threads_group_idx").on(table.groupId),
	],
);

export type Thread = typeof threads.$inferSelect;
export type NewThread = typeof threads.$inferInsert;

import { boolean, index, integer, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

import { workflowStatusEnum } from "./enums";
import { threads } from "./thread";
import { workspaces } from "./workspace";

export const workflows = pgTable(
	"workflows",
	{
		id: text("id").primaryKey(),
		threadId: text("thread_id").references(() => threads.id, {
			onDelete: "set null",
		}),
		workspaceId: text("workspace_id")
			.notNull()
			.references(() => workspaces.id, { onDelete: "cascade" }),
		userId: uuid("user_id").notNull(),
		title: text("title").notNull(),
		description: text("description"),
		status: workflowStatusEnum("status").notNull().default("waiting"),
		autoApprove: boolean("auto_approve").notNull().default(false),
		schemaVersion: integer("schema_version").notNull().default(1),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
		updatedAt: timestamp("updated_at", { withTimezone: true })
			.defaultNow()
			.notNull()
			.$onUpdate(() => new Date()),
	},
	(table) => [
		index("workflows_user_status_idx").on(table.userId, table.status),
		index("workflows_thread_idx").on(table.threadId),
	],
);

export type Workflow = typeof workflows.$inferSelect;
export type NewWorkflow = typeof workflows.$inferInsert;

import { pgTable, text, timestamp } from "drizzle-orm/pg-core";

import { planStatusEnum } from "./enums";
import { workflows } from "./workflow";

export const plans = pgTable("plans", {
	id: text("id").primaryKey(),
	workflowId: text("workflow_id")
		.notNull()
		.unique()
		.references(() => workflows.id, { onDelete: "cascade" }),
	title: text("title").notNull(),
	objective: text("objective"),
	summary: text("summary"),
	status: planStatusEnum("status").notNull().default("draft"),
	createdAt: timestamp("created_at", { withTimezone: true })
		.defaultNow()
		.notNull(),
	updatedAt: timestamp("updated_at", { withTimezone: true })
		.defaultNow()
		.notNull()
		.$onUpdate(() => new Date()),
});

export type Plan = typeof plans.$inferSelect;
export type NewPlan = typeof plans.$inferInsert;

import { integer, pgTable, text, timestamp, uniqueIndex } from "drizzle-orm/pg-core";

import { planStepStatusEnum } from "./enums";
import { plans } from "./plan";

export const planSteps = pgTable(
	"plan_steps",
	{
		id: text("id").primaryKey(),
		planId: text("plan_id")
			.notNull()
			.references(() => plans.id, { onDelete: "cascade" }),
		position: integer("position").notNull(),
		title: text("title").notNull(),
		description: text("description"),
		status: planStepStatusEnum("status").notNull().default("pending"),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
		updatedAt: timestamp("updated_at", { withTimezone: true })
			.defaultNow()
			.notNull()
			.$onUpdate(() => new Date()),
	},
	(table) => [
		uniqueIndex("plan_steps_plan_position_idx").on(table.planId, table.position),
	],
);

export type PlanStep = typeof planSteps.$inferSelect;
export type NewPlanStep = typeof planSteps.$inferInsert;

import { index, integer, jsonb, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

import { messageRoleEnum, messageStatusEnum } from "./enums";
import { threads } from "./thread";

export const chatMessages = pgTable(
	"chat_messages",
	{
		id: text("id").primaryKey(),
		threadId: text("thread_id")
			.notNull()
			.references(() => threads.id, { onDelete: "cascade" }),
		userId: uuid("user_id").notNull(),
		role: messageRoleEnum("role").notNull(),
		content: jsonb("content").notNull(),
		runId: text("run_id"),
		status: messageStatusEnum("status").notNull().default("completed"),
		queueOrder: integer("queue_order"),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
		updatedAt: timestamp("updated_at", { withTimezone: true })
			.defaultNow()
			.notNull()
			.$onUpdate(() => new Date()),
	},
	(table) => [
		index("chat_messages_thread_created_idx").on(table.threadId, table.createdAt),
		index("chat_messages_thread_status_idx").on(table.threadId, table.status),
	],
);

export type ChatMessage = typeof chatMessages.$inferSelect;
export type NewChatMessage = typeof chatMessages.$inferInsert;

import type { AnyPgColumn } from "drizzle-orm/pg-core";
import {
	bigint,
	index,
	jsonb,
	numeric,
	pgTable,
	text,
	timestamp,
	uuid,
} from "drizzle-orm/pg-core";

import { runStatusEnum, runTriggerEnum } from "./enums";
import { threads } from "./thread";

export const runs = pgTable(
	"runs",
	{
		id: text("id").primaryKey(),
		threadId: text("thread_id")
			.notNull()
			.references(() => threads.id, { onDelete: "cascade" }),
		workflowId: text("workflow_id"),
		userId: uuid("user_id").notNull(),
		trigger: runTriggerEnum("trigger").notNull(),
		rerunOf: text("rerun_of").references((): AnyPgColumn => runs.id, {
			onDelete: "set null",
		}),
		status: runStatusEnum("status").notNull().default("pending"),
		promptSnapshot: jsonb("prompt_snapshot"),
		costUsd: numeric("cost_usd", { precision: 10, scale: 6 }),
		tokenCount: bigint("token_count", { mode: "number" }),
		finishedAt: timestamp("finished_at", { withTimezone: true }),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
		updatedAt: timestamp("updated_at", { withTimezone: true })
			.defaultNow()
			.notNull()
			.$onUpdate(() => new Date()),
	},
	(table) => [
		index("runs_thread_created_idx").on(table.threadId, table.createdAt),
		index("runs_workflow_status_idx").on(table.workflowId, table.status),
	],
);

export type Run = typeof runs.$inferSelect;
export type NewRun = typeof runs.$inferInsert;

import type { AnyPgColumn } from "drizzle-orm/pg-core";
import { index, jsonb, pgTable, text, timestamp } from "drizzle-orm/pg-core";

import { activityStatusEnum, activityTypeEnum } from "./enums";
import { runs } from "./run";

export const runActivities = pgTable(
	"run_activities",
	{
		id: text("id").primaryKey(),
		runId: text("run_id")
			.notNull()
			.references(() => runs.id, { onDelete: "cascade" }),
		parentId: text("parent_id").references((): AnyPgColumn => runActivities.id, {
			onDelete: "set null",
		}),
		type: activityTypeEnum("type").notNull(),
		status: activityStatusEnum("status").notNull().default("pending"),
		stepLabel: text("step_label"),
		title: text("title"),
		description: text("description"),
		detail: jsonb("detail"),
		startedAt: timestamp("started_at", { withTimezone: true }),
		completedAt: timestamp("completed_at", { withTimezone: true }),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
	},
	(table) => [
		index("run_activities_run_created_idx").on(table.runId, table.createdAt),
	],
);

export type RunActivity = typeof runActivities.$inferSelect;
export type NewRunActivity = typeof runActivities.$inferInsert;

import { boolean, index, jsonb, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

import { approvalStatusEnum } from "./enums";
import { runs } from "./run";
import { threads } from "./thread";
import { workflows } from "./workflow";

export const approvalRequests = pgTable(
	"approval_requests",
	{
		id: text("id").primaryKey(),
		runId: text("run_id")
			.notNull()
			.references(() => runs.id, { onDelete: "cascade" }),
		workflowId: text("workflow_id").references(() => workflows.id, {
			onDelete: "set null",
		}),
		threadId: text("thread_id").references(() => threads.id, {
			onDelete: "set null",
		}),
		userId: uuid("user_id").notNull(),
		toolName: text("tool_name").notNull(),
		input: jsonb("input"),
		schema: jsonb("schema"),
		status: approvalStatusEnum("status").notNull().default("pending"),
		autoApproved: boolean("auto_approved").notNull().default(false),
		resolvedAt: timestamp("resolved_at", { withTimezone: true }),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
	},
	(table) => [
		index("approval_requests_status_created_idx").on(table.status, table.createdAt),
		index("approval_requests_thread_idx").on(table.threadId),
	],
);

export type ApprovalRequest = typeof approvalRequests.$inferSelect;
export type NewApprovalRequest = typeof approvalRequests.$inferInsert;

import { index, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

import { inviteKindEnum, inviteStatusEnum, threadRoleEnum } from "./enums";
import { threads } from "./thread";
import { workspaces } from "./workspace";

export const invites = pgTable(
	"invites",
	{
		id: text("id").primaryKey(),
		kind: inviteKindEnum("kind").notNull(),
		workspaceId: text("workspace_id")
			.notNull()
			.references(() => workspaces.id, { onDelete: "cascade" }),
		threadId: text("thread_id").references(() => threads.id, {
			onDelete: "set null",
		}),
		invitedBy: uuid("invited_by").notNull(),
		inviteeEmail: text("invitee_email").notNull(),
		invitedUserId: uuid("invited_user_id"),
		tokenHash: text("token_hash").notNull().unique(),
		role: threadRoleEnum("role").notNull().default("editor"),
		status: inviteStatusEnum("status").notNull().default("pending"),
		expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
		acceptedAt: timestamp("accepted_at", { withTimezone: true }),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
	},
	(table) => [
		index("invites_thread_idx").on(table.threadId),
		index("invites_token_hash_idx").on(table.tokenHash),
	],
);

export type Invite = typeof invites.$inferSelect;
export type NewInvite = typeof invites.$inferInsert;

import { pgTable, text, timestamp, uniqueIndex, uuid } from "drizzle-orm/pg-core";

import { threadRoleEnum } from "./enums";
import { invites } from "./invite";
import { threads } from "./thread";

export const threadShares = pgTable(
	"thread_shares",
	{
		id: text("id").primaryKey(),
		threadId: text("thread_id")
			.notNull()
			.references(() => threads.id, { onDelete: "cascade" }),
		userId: uuid("user_id").notNull(),
		role: threadRoleEnum("role").notNull().default("editor"),
		invitedBy: uuid("invited_by").notNull(),
		inviteId: text("invite_id").references(() => invites.id, {
			onDelete: "set null",
		}),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
	},
	(table) => [
		uniqueIndex("thread_shares_thread_user_idx").on(table.threadId, table.userId),
	],
);

export type ThreadShare = typeof threadShares.$inferSelect;
export type NewThreadShare = typeof threadShares.$inferInsert;

import { index, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

import { notificationTypeEnum } from "./enums";
import { threads } from "./thread";
import { workspaces } from "./workspace";

export const notifications = pgTable(
	"notifications",
	{
		id: text("id").primaryKey(),
		userId: uuid("user_id").notNull(),
		workspaceId: text("workspace_id")
			.notNull()
			.references(() => workspaces.id, { onDelete: "cascade" }),
		threadId: text("thread_id").references(() => threads.id, {
			onDelete: "set null",
		}),
		type: notificationTypeEnum("type").notNull(),
		title: text("title").notNull(),
		body: text("body").notNull().default(""),
		readAt: timestamp("read_at", { withTimezone: true }),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
	},
	(table) => [
		index("notifications_user_read_created_idx").on(
			table.userId,
			table.readAt,
			table.createdAt,
		),
	],
);

export type Notification = typeof notifications.$inferSelect;
export type NewNotification = typeof notifications.$inferInsert;

import { customType, pgTable, text, timestamp, uniqueIndex, uuid } from "drizzle-orm/pg-core";

import { apiProviderEnum } from "./enums";
import { workspaces } from "./workspace";

const bytea = customType<{ data: Buffer; notNull: false; default: false }>({
	dataType() {
		return "bytea";
	},
});

export const workspaceApiKeys = pgTable(
	"workspace_api_keys",
	{
		id: text("id").primaryKey(),
		workspaceId: text("workspace_id")
			.notNull()
			.references(() => workspaces.id, { onDelete: "cascade" }),
		createdBy: uuid("created_by").notNull(),
		provider: apiProviderEnum("provider").notNull(),
		keyEncrypted: bytea("key_encrypted").notNull(),
		modelName: text("model_name"),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
		updatedAt: timestamp("updated_at", { withTimezone: true })
			.defaultNow()
			.notNull()
			.$onUpdate(() => new Date()),
	},
	(table) => [
		uniqueIndex("workspace_api_keys_workspace_provider_idx").on(
			table.workspaceId,
			table.provider,
		),
	],
);

export type WorkspaceApiKey = typeof workspaceApiKeys.$inferSelect;
export type NewWorkspaceApiKey = typeof workspaceApiKeys.$inferInsert;

import { bigint, boolean, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

import { threads } from "./thread";
import { workspaces } from "./workspace";

export const files = pgTable("files", {
	id: text("id").primaryKey(),
	userId: uuid("user_id").notNull(),
	threadId: text("thread_id").references(() => threads.id, {
		onDelete: "set null",
	}),
	workspaceId: text("workspace_id")
		.notNull()
		.references(() => workspaces.id, { onDelete: "cascade" }),
	bucket: text("bucket").notNull().default("chat-attachments"),
	path: text("path").notNull(),
	mimeType: text("mime_type"),
	sizeBytes: bigint("size_bytes", { mode: "number" }),
	compressed: boolean("compressed").notNull().default(false),
	createdAt: timestamp("created_at", { withTimezone: true })
		.defaultNow()
		.notNull(),
});

export type File = typeof files.$inferSelect;
export type NewFile = typeof files.$inferInsert;

import { relations } from "drizzle-orm";

import { approvalRequests } from "./approval-request";
import { chatMessages } from "./chat-message";
import { files } from "./file";
import { groups } from "./group";
import { invites } from "./invite";
import { notifications } from "./notification";
import { plans } from "./plan";
import { planSteps } from "./plan-step";
import { runs } from "./run";
import { runActivities } from "./run-activity";
import { threads } from "./thread";
import { threadShares } from "./thread-share";
import { workspaceApiKeys } from "./workspace-api-key";
import { workspaceMembers } from "./workspace-member";
import { workspaces } from "./workspace";
import { workflows } from "./workflow";

// ── workspaces ──────────────────────────────────────────────────────

export const workspaceRelations = relations(workspaces, ({ many }) => ({
	groups: many(groups),
	members: many(workspaceMembers),
	threads: many(threads),
	workflows: many(workflows),
	notifications: many(notifications),
	apiKeys: many(workspaceApiKeys),
	files: many(files),
}));

// ── groups ──────────────────────────────────────────────────────────

export const groupRelations = relations(groups, ({ one, many }) => ({
	workspace: one(workspaces, {
		fields: [groups.workspaceId],
		references: [workspaces.id],
	}),
	threads: many(threads),
}));

// ── workspace_members ───────────────────────────────────────────────

export const workspaceMemberRelations = relations(workspaceMembers, ({ one }) => ({
	workspace: one(workspaces, {
		fields: [workspaceMembers.workspaceId],
		references: [workspaces.id],
	}),
}));

// ── threads ─────────────────────────────────────────────────────────

export const threadRelations = relations(threads, ({ one, many }) => ({
	workspace: one(workspaces, {
		fields: [threads.workspaceId],
		references: [workspaces.id],
	}),
	group: one(groups, {
		fields: [threads.groupId],
		references: [groups.id],
	}),
	workflows: many(workflows),
	chatMessages: many(chatMessages),
	runs: many(runs),
	shares: many(threadShares),
	invites: many(invites),
}));

// ── workflows ───────────────────────────────────────────────────────

export const workflowRelations = relations(workflows, ({ one, many }) => ({
	workspace: one(workspaces, {
		fields: [workflows.workspaceId],
		references: [workspaces.id],
	}),
	thread: one(threads, {
		fields: [workflows.threadId],
		references: [threads.id],
	}),
	plan: one(plans, {
		fields: [workflows.id],
		references: [plans.workflowId],
	}),
	runs: many(runs),
}));

// ── plans ───────────────────────────────────────────────────────────

export const planRelations = relations(plans, ({ one, many }) => ({
	workflow: one(workflows, {
		fields: [plans.workflowId],
		references: [workflows.id],
	}),
	steps: many(planSteps),
}));

// ── plan_steps ──────────────────────────────────────────────────────

export const planStepRelations = relations(planSteps, ({ one }) => ({
	plan: one(plans, {
		fields: [planSteps.planId],
		references: [plans.id],
	}),
}));

// ── chat_messages ───────────────────────────────────────────────────

export const chatMessageRelations = relations(chatMessages, ({ one }) => ({
	thread: one(threads, {
		fields: [chatMessages.threadId],
		references: [threads.id],
	}),
}));

// ── runs (self-ref `rerun_of` — relationName on BOTH sides) ─────────

export const runRelations = relations(runs, ({ one, many }) => ({
	thread: one(threads, {
		fields: [runs.threadId],
		references: [threads.id],
	}),
	workflow: one(workflows, {
		fields: [runs.workflowId],
		references: [workflows.id],
	}),
	rerunOf: one(runs, {
		fields: [runs.rerunOf],
		references: [runs.id],
		relationName: "rerunOf",
	}),
	reruns: many(runs, { relationName: "rerunOf" }),
	activities: many(runActivities),
	approvalRequests: many(approvalRequests),
}));

// ── run_activities (self-ref `parent_id` — relationName BOTH sides) ─

export const runActivityRelations = relations(runActivities, ({ one, many }) => ({
	run: one(runs, {
		fields: [runActivities.runId],
		references: [runs.id],
	}),
	parent: one(runActivities, {
		fields: [runActivities.parentId],
		references: [runActivities.id],
		relationName: "parent",
	}),
	children: many(runActivities, { relationName: "parent" }),
}));

// ── approval_requests ──────────────────────────────────────────────

export const approvalRequestRelations = relations(approvalRequests, ({ one }) => ({
	run: one(runs, {
		fields: [approvalRequests.runId],
		references: [runs.id],
	}),
	workflow: one(workflows, {
		fields: [approvalRequests.workflowId],
		references: [workflows.id],
	}),
	thread: one(threads, {
		fields: [approvalRequests.threadId],
		references: [threads.id],
	}),
}));

// ── invites ─────────────────────────────────────────────────────────

export const inviteRelations = relations(invites, ({ one }) => ({
	workspace: one(workspaces, {
		fields: [invites.workspaceId],
		references: [workspaces.id],
	}),
	thread: one(threads, {
		fields: [invites.threadId],
		references: [threads.id],
	}),
}));

// ── thread_shares ──────────────────────────────────────────────────

export const threadShareRelations = relations(threadShares, ({ one }) => ({
	thread: one(threads, {
		fields: [threadShares.threadId],
		references: [threads.id],
	}),
	invite: one(invites, {
		fields: [threadShares.inviteId],
		references: [invites.id],
	}),
}));

// ── notifications ──────────────────────────────────────────────────

export const notificationRelations = relations(notifications, ({ one }) => ({
	workspace: one(workspaces, {
		fields: [notifications.workspaceId],
		references: [workspaces.id],
	}),
	thread: one(threads, {
		fields: [notifications.threadId],
		references: [threads.id],
	}),
}));

// ── workspace_api_keys ─────────────────────────────────────────────

export const workspaceApiKeyRelations = relations(workspaceApiKeys, ({ one }) => ({
	workspace: one(workspaces, {
		fields: [workspaceApiKeys.workspaceId],
		references: [workspaces.id],
	}),
}));

// ── files ───────────────────────────────────────────────────────────

export const fileRelations = relations(files, ({ one }) => ({
	workspace: one(workspaces, {
		fields: [files.workspaceId],
		references: [workspaces.id],
	}),
	thread: one(threads, {
		fields: [files.threadId],
		references: [threads.id],
	}),
}));

