import { createServerSupabase } from "@aevryn/auth/server";
import { cookies } from "next/headers";

/**
 * Next.js server-side Supabase client (App Router).
 * Always create a fresh instance per request; `cookies()` is async.
 */
export async function createServerSupabaseForNext() {
	const cookieStore = await cookies();

	return createServerSupabase({
		getAll() {
			return cookieStore.getAll();
		},
		setAll(cookiesToSet) {
			try {
				cookiesToSet.forEach(({ name, value, options }) =>
					cookieStore.set(name, value, options),
				);
			} catch {
				// Called from a Server Component — cookie writes are handled by proxy.ts.
			}
		},
	});
}

import { getBrowserSupabase } from "@aevryn/auth";

/**
 * Shared browser Supabase client. Import from client components only.
 */
export const supabaseClient = getBrowserSupabase();

import { createServerSupabase, getCurrentUser } from "@aevryn/auth";
import type { CookieMethodsServer } from "@aevryn/auth";
import type { Request as EvlogRequest } from "evlog/next";

import { useLogger } from "@/lib/evlog";

function cookieMethodsFromRequest(req: Request): CookieMethodsServer {
	const cookies = new Map<string, string>();
	const header = req.headers.get("cookie");
	if (header) {
		for (const part of header.split(";")) {
			const eq = part.indexOf("=");
			if (eq <= 0) continue;
			const name = part.slice(0, eq).trim();
			const value = decodeURIComponent(part.slice(eq + 1).trim());
			if (name) cookies.set(name, value);
		}
	}
	return {
		getAll() {
			return Array.from(cookies, ([name, value]) => ({ name, value }));
		},
		setAll() {
			// Read-only: refresh is handled by proxy.ts.
		},
	};
}

/**
 * Best-effort identity enrichment for evlog when a session cookie is present.
 * Refresh of expired tokens is left to the proxy; this only reads the session.
 */
export async function identifyEvlogUser(req: EvlogRequest) {
	const supabase = createServerSupabase(cookieMethodsFromRequest(req));
	const user = await getCurrentUser(supabase);
	if (!user) return;
	useLogger({
		userId: user.id,
		email: user.email,
	});
}

